CREATE TABLE IF NOT EXISTS user (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, emailVerified INTEGER NOT NULL DEFAULT 0, image TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS session (id TEXT PRIMARY KEY, expiresAt INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, ipAddress TEXT, userAgent TEXT, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS account (id TEXT PRIMARY KEY, accountId TEXT NOT NULL, providerId TEXT NOT NULL, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, accessToken TEXT, refreshToken TEXT, idToken TEXT, accessTokenExpiresAt INTEGER, refreshTokenExpiresAt INTEGER, scope TEXT, password TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expiresAt INTEGER NOT NULL, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS workspace (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, owner_user_id TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS workspace_membership (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, user_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','admin','editor','viewer')), invitation_status TEXT NOT NULL DEFAULT 'accepted', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(workspace_id, user_id));
CREATE TABLE IF NOT EXISTS site (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, name TEXT NOT NULL, slug TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', homepage_page_id TEXT, project_schema_version INTEGER NOT NULL DEFAULT 2, theme_data TEXT NOT NULL DEFAULT '{}', settings_data TEXT NOT NULL DEFAULT '{}', custom_code_metadata TEXT NOT NULL DEFAULT '{}', created_by TEXT NOT NULL, updated_by TEXT NOT NULL, current_revision INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(workspace_id, slug));
CREATE TABLE IF NOT EXISTS page (id TEXT PRIMARY KEY, site_id TEXT NOT NULL, name TEXT NOT NULL, slug TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, homepage INTEGER NOT NULL DEFAULT 0, show_in_navigation INTEGER NOT NULL DEFAULT 1, password_protected INTEGER NOT NULL DEFAULT 0, seo_title TEXT NOT NULL DEFAULT '', seo_description TEXT NOT NULL DEFAULT '', canonical_url TEXT, project_data TEXT NOT NULL DEFAULT '{}', deleted_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(site_id, slug));
CREATE TABLE IF NOT EXISTS site_revision (id TEXT PRIMARY KEY, site_id TEXT NOT NULL, revision_number INTEGER NOT NULL, name TEXT NOT NULL, snapshot_data TEXT NOT NULL, created_by TEXT NOT NULL, restore_source_revision INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(site_id, revision_number));
CREATE TABLE IF NOT EXISTS asset_metadata (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, site_id TEXT NOT NULL, filename TEXT NOT NULL, mime_type TEXT NOT NULL, size INTEGER NOT NULL, alt_text TEXT NOT NULL DEFAULT '', storage_status TEXT NOT NULL DEFAULT 'metadata_only', created_by TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit_event (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, user_id TEXT NOT NULL, site_id TEXT, action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, metadata TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS membership_workspace_lookup ON workspace_membership(workspace_id);
CREATE INDEX IF NOT EXISTS membership_user_lookup ON workspace_membership(user_id);
CREATE INDEX IF NOT EXISTS site_workspace_lookup ON site(workspace_id);
CREATE INDEX IF NOT EXISTS page_site_lookup ON page(site_id);
CREATE INDEX IF NOT EXISTS revision_site_lookup ON site_revision(site_id);
CREATE INDEX IF NOT EXISTS audit_workspace_lookup ON audit_event(workspace_id, created_at);
